UPDATE clubs c
SET address = cls.address,
    description = concat_ws(
        E'\n\n',
        NULLIF(c.description, ''),
        'Reviewed by TASK-3027: ' || cls.rationale
    )
FROM club_location_cleanup_classification cls
WHERE c.id = cls.club_id
  AND (c.address IS NULL OR btrim(c.address) = '' OR c.address IS DISTINCT FROM cls.address);

