UPDATE shows s
SET production_company_id = pc.id
FROM production_companies pc
WHERE s.club_id = 539
  AND pc.slug = 'kricket-comedy'
  AND s.production_company_id IS DISTINCT FROM pc.id;

UPDATE shows s
SET production_company_id = pc.id
FROM production_companies pc
WHERE s.club_id = 556
  AND pc.slug = 'coastal-entertainment-productions'
  AND s.production_company_id IS DISTINCT FROM pc.id;

UPDATE shows s
SET production_company_id = pc.id
FROM production_companies pc
WHERE s.club_id = 620
  AND pc.slug = 'comedy-shows-near-me'
  AND s.production_company_id IS DISTINCT FROM pc.id;

DO $$
DECLARE
    blank_count integer;
    unstamped_count integer;
BEGIN
    SELECT count(*) INTO blank_count
    FROM clubs
    WHERE address IS NULL OR btrim(address) = '';

    IF blank_count <> 0 THEN
        RAISE EXCEPTION 'TASK-3027 left % clubs with blank addresses', blank_count;
    END IF;

    SELECT count(*) INTO unstamped_count
    FROM shows s
    WHERE s.club_id IN (539, 556, 620)
      AND s.production_company_id IS NULL;

    IF unstamped_count <> 0 THEN
        RAISE EXCEPTION 'TASK-3027 left % producer/aggregator shows without production_company_id', unstamped_count;
    END IF;
END $$;
